-- CANONICAL STORE. Projection section belongs in an independent consumer database.
PRAGMA foreign_keys=ON;
CREATE TABLE streams(id TEXT PRIMARY KEY, generation TEXT NOT NULL, name TEXT NOT NULL UNIQUE, revision INTEGER NOT NULL CHECK(revision>0), admission_paused INTEGER NOT NULL CHECK(admission_paused IN(0,1)), low_water INTEGER NOT NULL CHECK(low_water>=0), high_water INTEGER NOT NULL, capacity_bytes INTEGER NOT NULL CHECK(capacity_bytes>0), policy_json TEXT NOT NULL CHECK(json_valid(policy_json)), CHECK(low_water<=high_water), UNIQUE(id,generation));
CREATE TABLE append_receipts(producer_id TEXT NOT NULL, request_key TEXT NOT NULL, stream_id TEXT NOT NULL REFERENCES streams(id), generation TEXT NOT NULL, request_digest TEXT NOT NULL, start_offset INTEGER NOT NULL CHECK(start_offset>=0), end_exclusive INTEGER NOT NULL, response_json TEXT NOT NULL, PRIMARY KEY(producer_id,request_key), CHECK(end_exclusive>start_offset));
CREATE TABLE segments(id TEXT PRIMARY KEY, stream_id TEXT NOT NULL REFERENCES streams(id), start_offset INTEGER NOT NULL CHECK(start_offset>=0), end_exclusive INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN('OPEN','SEALED')), record_count INTEGER NOT NULL CHECK(record_count>=0), byte_count INTEGER NOT NULL CHECK(byte_count>=0), digest TEXT, CHECK(end_exclusive>=start_offset), CHECK(state='OPEN' OR (digest IS NOT NULL AND length(digest)=64)), UNIQUE(stream_id,start_offset));
CREATE UNIQUE INDEX one_open_segment ON segments(stream_id) WHERE state='OPEN';
CREATE TABLE events(stream_id TEXT NOT NULL REFERENCES streams(id), offset INTEGER NOT NULL CHECK(offset>=0), segment_id TEXT NOT NULL REFERENCES segments(id), event_type TEXT NOT NULL, schema_version INTEGER NOT NULL CHECK(schema_version>0), payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), digest TEXT NOT NULL CHECK(length(digest)=64), producer_id TEXT NOT NULL, request_key TEXT NOT NULL, accepted_at INTEGER NOT NULL, PRIMARY KEY(stream_id,offset), FOREIGN KEY(producer_id,request_key) REFERENCES append_receipts(producer_id,request_key));
CREATE TABLE consumer_groups(id TEXT PRIMARY KEY, stream_id TEXT NOT NULL, generation TEXT NOT NULL, name TEXT NOT NULL, next_offset INTEGER NOT NULL CHECK(next_offset>=0), state TEXT NOT NULL CHECK(state IN('ACTIVE','PAUSED','RETIRED')), revision INTEGER NOT NULL CHECK(revision>0), owner_instance TEXT, owner_epoch INTEGER NOT NULL CHECK(owner_epoch>=0), lease_expires_at INTEGER, delivered_end_exclusive INTEGER NOT NULL CHECK(delivered_end_exclusive>=0), UNIQUE(stream_id,name), FOREIGN KEY(stream_id,generation) REFERENCES streams(id,generation));
CREATE TABLE checkpoint_receipts(group_id TEXT NOT NULL REFERENCES consumer_groups(id), instance_id TEXT NOT NULL, request_key TEXT NOT NULL, request_digest TEXT NOT NULL, committed_offset INTEGER NOT NULL CHECK(committed_offset>=0), response_json TEXT NOT NULL, PRIMARY KEY(group_id,instance_id,request_key));
CREATE TABLE replays(id TEXT PRIMARY KEY, stream_id TEXT NOT NULL REFERENCES streams(id), group_id TEXT NOT NULL UNIQUE REFERENCES consumer_groups(id), projection_id TEXT NOT NULL UNIQUE, start_offset INTEGER NOT NULL CHECK(start_offset>=0), end_exclusive INTEGER NOT NULL, protected_start INTEGER, state TEXT NOT NULL CHECK(state IN('CREATED','RUNNING','PAUSED','SUCCEEDED','FAILED','CANCELLED')), revision INTEGER NOT NULL CHECK(revision>0), CHECK(end_exclusive>=start_offset));
CREATE TABLE control_receipts(actor TEXT NOT NULL, operation TEXT NOT NULL, target TEXT NOT NULL, request_key TEXT NOT NULL, digest TEXT NOT NULL, response_json TEXT NOT NULL, PRIMARY KEY(actor,operation,target,request_key));
CREATE TABLE audit(stream_id TEXT NOT NULL REFERENCES streams(id), sequence INTEGER NOT NULL CHECK(sequence>0), event_type TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), PRIMARY KEY(stream_id,sequence));
CREATE INDEX group_retention ON consumer_groups(stream_id,state,next_offset);
CREATE INDEX owner_expiry ON consumer_groups(lease_expires_at) WHERE owner_instance IS NOT NULL;
CREATE INDEX segment_bounds ON segments(stream_id,state,start_offset,end_exclusive);
-- PROJECTION STORE. No foreign keys to canonical tables.
CREATE TABLE projection_meta(projection_id TEXT PRIMARY KEY, stream_id TEXT NOT NULL, generation TEXT NOT NULL, reducer_version INTEGER NOT NULL CHECK(reducer_version>0), next_offset INTEGER NOT NULL CHECK(next_offset>=0));
CREATE TABLE applied_events(projection_id TEXT NOT NULL REFERENCES projection_meta(projection_id), generation TEXT NOT NULL, offset INTEGER NOT NULL CHECK(offset>=0), digest TEXT NOT NULL, PRIMARY KEY(projection_id,generation,offset));
CREATE TABLE devices(projection_id TEXT NOT NULL REFERENCES projection_meta(projection_id), device_id TEXT NOT NULL, label TEXT NOT NULL, retired INTEGER NOT NULL CHECK(retired IN(0,1)), reading INTEGER, PRIMARY KEY(projection_id,device_id));
CREATE TABLE summary(projection_id TEXT NOT NULL REFERENCES projection_meta(projection_id), metric TEXT NOT NULL, value INTEGER NOT NULL, PRIMARY KEY(projection_id,metric));
-- Application transaction guards enforce contiguous offsets, current epoch,
-- delivered bounds, immutable records and safe sealed-prefix retention.
-- Receipts deliberately do not reference individual prunable event rows.
